window.SCIENCE_CH2_FALLBACK = {"chapter": "Chapter 2: The Invisible Living World: Beyond Our Naked Eye", "source": "Class 8 Science (NCERT & BHU CHS Class 9 Entrance Exam Level)", "totalQuestions": 140, "questions": [{"id": 1, "topic": "Discovery of Cell & Microscopy", "difficulty": "Easy", "question": "Who coined the term 'cell' in 1665 after observing thin slices of cork under a self-designed microscope?", "options": ["Antonie van Leeuwenhoek", "Robert Hooke", "Robert Brown", "Matthias Schleiden"], "correctIndex": 1, "explanation": "Robert Hooke observed honeycomb-like empty compartments in dead cork slices in 1665 and named them 'cells' (from Latin 'cellula', meaning a little room).", "ncertRef": "CHS Core • Cell Discovery"}, {"id": 2, "topic": "Discovery of Cell & Microscopy", "difficulty": "Easy", "question": "Which scientist is widely regarded as the 'Father of Microbiology' for being the first to observe living bacteria and protozoa?", "options": ["Edward Jenner", "Antonie van Leeuwenhoek", "Louis Pasteur", "Robert Hooke"], "correctIndex": 1, "explanation": "In the 1670s, Dutch scientist Antonie van Leeuwenhoek used superior single-lens microscopes to observe living 'animalcules' (bacteria and protozoa) in pond water.", "ncertRef": "CHS Core • Microbiology Pioneers"}, {"id": 3, "topic": "Discovery of Cell & Microscopy", "difficulty": "Medium", "question": "What was the title of the famous 1665 book in which Robert Hooke published his microscopic drawings of cork cells?", "options": ["Origin of Species", "Micrographia", "Philosophia Botanica", "Systema Naturae"], "correctIndex": 1, "explanation": "Robert Hooke published 'Micrographia' in 1665, containing detailed copperplate illustrations of cork cells, fleas, and other microscopic objects.", "ncertRef": "CHS High-Yield • History of Science"}, {"id": 4, "topic": "Discovery of Cell & Microscopy", "difficulty": "Easy", "question": "The cells that Robert Hooke first observed in a thin slice of cork were actually:", "options": ["Living animal cells with nuclei", "Dead plant cells with rigid cell walls", "Multicellular fungal hyphae", "Living bacterial cells"], "correctIndex": 1, "explanation": "Cork comes from the bark of an oak tree and consists of dead plant cells; Hooke actually saw only their empty, box-like cell walls.", "ncertRef": "CHS Conceptual • Cell Discovery"}, {"id": 5, "topic": "Discovery of Cell & Microscopy", "difficulty": "Medium", "question": "Who discovered the nucleus inside plant cells in 1831?", "options": ["Rudolf Virchow", "Robert Hooke", "Robert Brown", "Theodor Schwann"], "correctIndex": 2, "explanation": "Scottish botanist Robert Brown discovered and named the cell nucleus in 1831 while studying orchid root cells.", "ncertRef": "CHS High-Yield • Scientists"}, {"id": 6, "topic": "Discovery of Cell & Microscopy", "difficulty": "Medium", "question": "The classic Cell Theory, stating that all plants and animals are composed of cells, was formulated in 1838–1839 by:", "options": ["Louis Pasteur and Robert Koch", "Watson and Crick", "Robert Hooke and Robert Brown", "Matthias Schleiden and Theodor Schwann"], "correctIndex": 3, "explanation": "Botanist Matthias Schleiden (1838) and zoologist Theodor Schwann (1839) jointly proposed that all living organisms are made of cells.", "ncertRef": "CHS High-Yield • Cell Theory"}, {"id": 7, "topic": "Discovery of Cell & Microscopy", "difficulty": "Hard", "question": "Who expanded the Cell Theory in 1855 with the famous Latin phrase 'Omnis cellula-e-cellula', meaning all cells arise from pre-existing cells?", "options": ["J. E. Purkinje", "Camillo Golgi", "Antonie van Leeuwenhoek", "Rudolf Virchow"], "correctIndex": 3, "explanation": "Rudolf Virchow established in 1855 that new cells are formed only by the division of pre-existing cells, completing the modern Cell Theory.", "ncertRef": "CHS Exam Favorite • Cell Theory"}, {"id": 8, "topic": "Discovery of Cell & Microscopy", "difficulty": "Medium", "question": "Who coined the term 'protoplasm' for the living fluid substance inside a cell?", "options": ["J. E. Purkinje", "Robert Brown", "Robert Hooke", "Alexander Fleming"], "correctIndex": 0, "explanation": "In 1839, Czech physiologist J. E. Purkinje coined the term 'protoplasm' to describe the living contents (cytoplasm + nucleus) of a cell.", "ncertRef": "CHS High-Yield • Terminology"}, {"id": 9, "topic": "Discovery of Cell & Microscopy", "difficulty": "Easy", "question": "Why is a curved glass piece used for magnifying tiny objects called a 'lens'?", "options": ["Because its shape resembles a lentil seed (thick in the middle, thin at the edges)", "Because it was invented in a city named Lens", "Because it only bends light from the Sun", "Because it is always made from liquid glass"], "correctIndex": 0, "explanation": "The word 'lens' comes from the Latin word for 'lentil', as a convex magnifying glass is thick in the center and thin at the edges like a lentil seed.", "ncertRef": "CHS Conceptual • Optics & Microscopy"}, {"id": 10, "topic": "Discovery of Cell & Microscopy", "difficulty": "Easy", "question": "Which two lenses work together in a compound light microscope to produce high magnification?", "options": ["Condenser lens and Mirror only", "Objective lens and Eyepiece (ocular) lens", "Diaphragm and Stage clip", "Concave lens and Prism"], "correctIndex": 1, "explanation": "A compound microscope uses an objective lens near the specimen and an eyepiece lens near the eye; total magnification is the product of both.", "ncertRef": "CHS Core • Compound Microscope"}, {"id": 11, "topic": "Discovery of Cell & Microscopy", "difficulty": "Medium", "question": "If a compound microscope has a 10× eyepiece lens and a 40× objective lens, what is its total magnification?", "options": ["400×", "50×", "4000×", "4×"], "correctIndex": 0, "explanation": "Total magnification of a compound microscope equals Eyepiece magnification × Objective magnification = 10 × 40 = 400×.", "ncertRef": "CHS Numerical • Microscopy"}, {"id": 12, "topic": "Discovery of Cell & Microscopy", "difficulty": "Medium", "question": "Why do biologists stain transparent cells with dyes like safranin or methylene blue before viewing them under a microscope?", "options": ["To increase contrast so cell boundaries and organelles become clearly visible", "To make the cells multiply faster", "To kill viruses living on the glass slide", "To permanently freeze the cells"], "correctIndex": 0, "explanation": "Most cells are nearly colourless and transparent; biological stains selectively colour parts like the cell wall and nucleus, making them easy to distinguish.", "ncertRef": "CHS Conceptual • Slide Preparation"}, {"id": 13, "topic": "Discovery of Cell & Microscopy", "difficulty": "Medium", "question": "Which stain is commonly used in school laboratories to highlight the nucleus and cell membrane of human cheek cells?", "options": ["Litmus solution", "Methylene blue", "Phenolphthalein", "Lime water"], "correctIndex": 1, "explanation": "Methylene blue is a basic blue dye that binds strongly to nucleic acids and clearly stains the nucleus and cytoplasm of animal cells like cheek cells.", "ncertRef": "CHS Practical Concept • Staining"}, {"id": 14, "topic": "Discovery of Cell & Microscopy", "difficulty": "Medium", "question": "Which red biological stain is typically used to stain plant cells such as onion peel cells for microscopic observation?", "options": ["Methyl orange", "Copper sulphate", "Turmeric extract", "Safranin"], "correctIndex": 3, "explanation": "Safranin imparts a pinkish-red colour to plant cell walls and nuclei, making onion epidermal cells sharply visible under a light microscope.", "ncertRef": "CHS Practical Concept • Staining"}, {"id": 15, "topic": "Discovery of Cell & Microscopy", "difficulty": "Medium", "question": "Why is a drop of glycerin placed on a specimen before lowering the coverslip during temporary slide preparation?", "options": ["To digest the cytoplasm", "To prevent the cells from drying out and improve optical clarity", "To dissolve the cell wall completely", "To convert plant cells into animal cells"], "correctIndex": 1, "explanation": "Glycerin keeps the tissue moist so cells do not shrivel due to dehydration, and its refractive index improves image sharpness.", "ncertRef": "CHS Practical Concept • Slide Preparation"}, {"id": 16, "topic": "Discovery of Cell & Microscopy", "difficulty": "Medium", "question": "Why should a coverslip be lowered gently at a 45° angle onto a microscope slide using a needle?", "options": ["To avoid trapping air bubbles under the coverslip", "To evaporate the stain immediately", "To break the glass slide evenly", "To crush the nucleus for better viewing"], "correctIndex": 0, "explanation": "Lowering the coverslip slowly at an angle pushes air out smoothly, preventing dark circular air bubbles from obstructing the view of cells.", "ncertRef": "CHS Practical Concept • Microscopy"}, {"id": 17, "topic": "Discovery of Cell & Microscopy", "difficulty": "Hard", "question": "Which type of microscope uses a beam of electrons instead of visible light to reveal ultra-tiny structures like viruses and ribosomes?", "options": ["Dissecting stereo microscope", "Simple magnifying lens", "Periscope", "Electron microscope"], "correctIndex": 3, "explanation": "An electron microscope uses high-energy electron beams and electromagnetic lenses to achieve magnifications up to 1,000,000×, revealing viruses and fine organelles.", "ncertRef": "CHS High-Yield • Microscopy"}, {"id": 18, "topic": "Discovery of Cell & Microscopy", "difficulty": "Hard", "question": "Which of the following is an exception to the Cell Theory because it lacks a cellular structure and cannot reproduce independently?", "options": ["Bacterium", "Virus", "Yeast", "Amoeba"], "correctIndex": 1, "explanation": "Viruses are acellular (non-cellular) particles made of genetic material inside a protein coat; they do not possess cytoplasm, organelles, or independent metabolism.", "ncertRef": "CHS Exam Favorite • Cell Theory"}, {"id": 19, "topic": "Discovery of Cell & Microscopy", "difficulty": "Easy", "question": "What is the standard unit used to measure the microscopic size of cells and bacteria?", "options": ["Light-year", "Kilometre (km)", "Micrometre (µm)", "Decibel (dB)"], "correctIndex": 2, "explanation": "Cells typically measure between 1 µm and 100 µm, where 1 micrometre equals one-millionth of a metre (10⁻⁶ m).", "ncertRef": "CHS Core • Units & Measurement"}, {"id": 20, "topic": "Discovery of Cell & Microscopy", "difficulty": "Hard", "question": "One micrometre (1 µm) is equal to how many millimetres?", "options": ["0.000001 mm (10⁻⁶ mm)", "0.1 mm (10⁻¹ mm)", "0.001 mm (10⁻³ mm)", "100 mm"], "correctIndex": 2, "explanation": "Since 1 m = 1,000 mm and 1 m = 1,000,000 µm, 1 µm = 1/1000 mm = 0.001 mm.", "ncertRef": "CHS Numerical • Units"}, {"id": 21, "topic": "Cell Structure & Organelles", "difficulty": "Easy", "question": "Which three basic components are present in almost every eukaryotic cell?", "options": ["Cell wall, chloroplast, and flagellum", "Cell membrane, cytoplasm, and nucleus", "Cilia, capsule, and plasmid", "Vacuole, starch grain, and chlorophyll"], "correctIndex": 1, "explanation": "The plasma (cell) membrane, jelly-like cytoplasm, and control-centre nucleus are the three fundamental parts of a typical eukaryotic cell.", "ncertRef": "CHS Core • Cell Structure"}, {"id": 22, "topic": "Cell Structure & Organelles", "difficulty": "Easy", "question": "Why is the plasma membrane described as 'selectively permeable'?", "options": ["It allows all solids and liquids to pass freely without restriction", "It completely blocks water and oxygen from entering the cell", "It is made of solid metal sheets", "It allows only certain essential substances to enter or leave the cell while blocking others"], "correctIndex": 3, "explanation": "The plasma membrane regulates transport by permitting useful molecules like oxygen, water, and nutrients to cross while keeping harmful substances out.", "ncertRef": "CHS Core • Cell Membrane"}, {"id": 23, "topic": "Cell Structure & Organelles", "difficulty": "Easy", "question": "Which rigid outer covering gives plant cells a definite box-like shape and protects them from bursting?", "options": ["Golgi body", "Cell wall", "Nuclear membrane", "Cytoplasm"], "correctIndex": 1, "explanation": "Plant cells have a non-living, rigid cell wall made mainly of cellulose outside the plasma membrane for mechanical strength and protection.", "ncertRef": "CHS Core • Plant Cell"}, {"id": 24, "topic": "Cell Structure & Organelles", "difficulty": "Medium", "question": "What is the primary chemical substance that makes up the cell wall of green plants?", "options": ["Glycogen", "Haemoglobin", "Chitin", "Cellulose"], "correctIndex": 3, "explanation": "Plant cell walls are composed primarily of cellulose, a tough complex carbohydrate (polysaccharide) that provides structural rigidity.", "ncertRef": "CHS High-Yield • Biomolecules"}, {"id": 25, "topic": "Cell Structure & Organelles", "difficulty": "Hard", "question": "While plant cell walls are made of cellulose, fungal cell walls are primarily composed of:", "options": ["Starch", "Calcium carbonate", "Keratin", "Chitin"], "correctIndex": 3, "explanation": "Fungi possess rigid cell walls made of chitin (a nitrogen-containing polysaccharide), distinguishing them chemically from plants.", "ncertRef": "CHS High-Yield • Plant vs Fungi"}, {"id": 26, "topic": "Cell Structure & Organelles", "difficulty": "Easy", "question": "Which cell organelle is known as the 'Powerhouse of the Cell' because it releases energy during cellular respiration?", "options": ["Mitochondria", "Centrosome", "Ribosome", "Vacuole"], "correctIndex": 0, "explanation": "Mitochondria oxidize food (glucose) in the presence of oxygen to generate energy stored in the form of ATP molecules.", "ncertRef": "CHS Exam Favorite • Organelles"}, {"id": 27, "topic": "Cell Structure & Organelles", "difficulty": "Medium", "question": "In what chemical form is energy stored and supplied by mitochondria inside living cells?", "options": ["DNA (Deoxyribonucleic Acid)", "CO₂ (Carbon Dioxide)", "NaCl (Sodium Chloride)", "ATP (Adenosine Triphosphate)"], "correctIndex": 3, "explanation": "ATP is called the 'energy currency of the cell' because mitochondria synthesize it to power all cellular activities.", "ncertRef": "CHS High-Yield • Bioenergetics"}, {"id": 28, "topic": "Cell Structure & Organelles", "difficulty": "Easy", "question": "Which green-coloured plastids are called the 'Kitchen of the Cell' because they carry out photosynthesis?", "options": ["Chloroplasts", "Lysosomes", "Leucoplasts", "Ribosomes"], "correctIndex": 0, "explanation": "Chloroplasts contain the green pigment chlorophyll, which traps sunlight to synthesize glucose from carbon dioxide and water.", "ncertRef": "CHS Core • Plastids"}, {"id": 29, "topic": "Cell Structure & Organelles", "difficulty": "Medium", "question": "Which colourless plastids found in roots and underground stems store starch, oils, and proteins?", "options": ["Chloroplasts", "Mitochondria", "Leucoplasts", "Chromoplasts"], "correctIndex": 2, "explanation": "Leucoplasts are colourless storage plastids abundant in non-green parts like potato tubers, roots, and seeds.", "ncertRef": "CHS High-Yield • Plastids"}, {"id": 30, "topic": "Cell Structure & Organelles", "difficulty": "Medium", "question": "Which coloured plastids give bright yellow, orange, and red colours to flowers and ripe fruits to attract pollinators?", "options": ["Leucoplasts", "Ribosomes", "Nucleoli", "Chromoplasts"], "correctIndex": 3, "explanation": "Chromoplasts contain carotenoid pigments that impart vivid colours to petals and ripening fruits, aiding pollination and seed dispersal.", "ncertRef": "CHS High-Yield • Plastids"}, {"id": 31, "topic": "Cell Structure & Organelles", "difficulty": "Easy", "question": "Which organelle acts as the 'Control Centre' of the cell and carries hereditary information?", "options": ["Vacuole", "Nucleus", "Cytoplasm", "Cell wall"], "correctIndex": 1, "explanation": "The nucleus directs cellular growth, metabolism, and reproduction, and houses chromosomes carrying hereditary genes.", "ncertRef": "CHS Core • Nucleus"}, {"id": 32, "topic": "Cell Structure & Organelles", "difficulty": "Medium", "question": "Thread-like structures present inside the nucleus that carry genes from parents to offspring are called:", "options": ["Cilia", "Chromosomes", "Vacuoles", "Pseudopodia"], "correctIndex": 1, "explanation": "Chromosomes are composed of DNA and proteins; segments of DNA on chromosomes are called genes, the units of inheritance.", "ncertRef": "CHS Core • Genetics Basics"}, {"id": 33, "topic": "Cell Structure & Organelles", "difficulty": "Medium", "question": "What is the functional unit of inheritance located on chromosomes?", "options": ["Cell wall", "Plastid", "Vacuole", "Gene"], "correctIndex": 3, "explanation": "A gene is a specific segment of DNA on a chromosome that controls a particular inherited trait, such as eye colour or blood group.", "ncertRef": "CHS Core • Genetics Basics"}, {"id": 34, "topic": "Cell Structure & Organelles", "difficulty": "Medium", "question": "Which organelle is nicknamed the 'Suicidal Bag of the Cell' because it contains strong digestive enzymes?", "options": ["Lysosome", "Ribosome", "Nucleolus", "Chloroplast"], "correctIndex": 0, "explanation": "Lysosomes contain hydrolytic enzymes that digest worn-out organelles and foreign invaders; if the cell is severely damaged, they can burst and digest the cell itself.", "ncertRef": "CHS Exam Favorite • Organelles"}, {"id": 35, "topic": "Cell Structure & Organelles", "difficulty": "Medium", "question": "Which tiny non-membrane-bound organelles are known as the 'Protein Factories of the Cell'?", "options": ["Lysosomes", "Plastids", "Vacuoles", "Ribosomes"], "correctIndex": 3, "explanation": "Ribosomes are the sites of protein synthesis in both prokaryotic and eukaryotic cells.", "ncertRef": "CHS Exam Favorite • Organelles"}, {"id": 36, "topic": "Cell Structure & Organelles", "difficulty": "Hard", "question": "Which organelle packages, modifies, and dispatches proteins and lipids inside and outside the cell, acting like a 'Post Office'?", "options": ["Cell wall", "Mitochondria", "Golgi apparatus", "Chromoplast"], "correctIndex": 2, "explanation": "The Golgi apparatus (discovered by Camillo Golgi) processes, packages, and secretes proteins and lipids synthesized in the endoplasmic reticulum.", "ncertRef": "CHS High-Yield • Organelles"}, {"id": 37, "topic": "Cell Structure & Organelles", "difficulty": "Easy", "question": "How does the vacuole of a mature plant cell typically differ from vacuoles in an animal cell?", "options": ["Animal cells have a single huge vacuole occupying 90% of the cell", "Plant cells never have vacuoles", "A mature plant cell has a single large central vacuole, whereas animal cells have small, temporary vacuoles or none", "Vacuoles in animal cells perform photosynthesis"], "correctIndex": 2, "explanation": "In mature plant cells, a large central vacuole stores cell sap and maintains turgidity, pushing the nucleus toward the periphery.", "ncertRef": "CHS Core • Plant vs Animal Cell"}, {"id": 38, "topic": "Cell Structure & Organelles", "difficulty": "Medium", "question": "Which of the following pairs of structures is present in a typical plant cell but ABSENT in an animal cell?", "options": ["Cell membrane and Cytoplasm", "Ribosomes and DNA", "Cell wall and Chloroplasts", "Nucleus and Mitochondria"], "correctIndex": 2, "explanation": "Animal cells lack both a rigid cell wall and plastids (including chloroplasts), though they share a plasma membrane, cytoplasm, nucleus, and mitochondria with plant cells.", "ncertRef": "CHS Core • Plant vs Animal Cell"}, {"id": 39, "topic": "Cell Structure & Organelles", "difficulty": "Hard", "question": "Cells that lack a well-defined nuclear membrane and membrane-bound organelles (such as bacteria) are called:", "options": ["Multicellular tissue cells", "Plant epidermal cells", "Eukaryotic cells", "Prokaryotic cells"], "correctIndex": 3, "explanation": "Prokaryotes (pro = primitive, karyon = nucleus) like bacteria and blue-green algae have naked genetic material in a nucleoid region without a nuclear membrane.", "ncertRef": "CHS Exam Favorite • Prokaryotes"}, {"id": 40, "topic": "Cell Structure & Organelles", "difficulty": "Hard", "question": "Which two organelles in a eukaryotic plant cell possess their own DNA and ribosomes, allowing them to make some of their own proteins?", "options": ["Golgi apparatus and Cell wall", "Vacuoles and Lysosomes", "Mitochondria and Chloroplasts", "Endoplasmic reticulum and Centrosome"], "correctIndex": 2, "explanation": "Mitochondria and plastids (chloroplasts) are semi-autonomous organelles because they contain their own circular DNA and 70S ribosomes.", "ncertRef": "CHS Advanced • Semi-autonomous Organelles"}, {"id": 41, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Easy", "question": "Which is the largest known single cell in the living world, easily visible to the naked eye?", "options": ["Ostrich egg", "Amoeba", "Onion peel cell", "Human nerve cell"], "correctIndex": 0, "explanation": "An unfertilized ostrich egg is a single cell measuring about 130–170 mm in diameter, making it the largest known cell.", "ncertRef": "CHS Exam Favorite • Cell Extremes"}, {"id": 42, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Hard", "question": "Which is the smallest known living cell, lacking a cell wall and measuring roughly 0.1 to 0.3 µm?", "options": ["Paramecium", "Human red blood cell", "Chlamydomonas", "Mycoplasma (PPLO)"], "correctIndex": 3, "explanation": "Mycoplasma (Pleuro-Pneumonia Like Organism or PPLO) is the smallest self-replicating cellular organism known.", "ncertRef": "CHS Exam Favorite • Cell Extremes"}, {"id": 43, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Easy", "question": "Which is the longest cell in the human body, capable of reaching up to 1 metre in length?", "options": ["White blood cell (WBC)", "Red blood cell (RBC)", "Cheek epithelial cell", "Nerve cell (Neuron)"], "correctIndex": 3, "explanation": "Nerve cells (neurons) have long branched extensions (axons) that transmit electrical impulses rapidly across long distances in the body.", "ncertRef": "CHS Core • Specialized Cells"}, {"id": 44, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Easy", "question": "Which single-celled organism and which human blood cell are both famous for continuously changing their shape?", "options": ["Spirogyra and Muscle cell", "Amoeba and White Blood Cell (WBC)", "Paramecium and Nerve cell", "Yeast and Red Blood Cell"], "correctIndex": 1, "explanation": "Amoeba changes shape using pseudopodia to move and capture food, while human WBCs change shape to squeeze through capillaries and engulf germs.", "ncertRef": "CHS Exam Favorite • Cell Shape"}, {"id": 45, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Medium", "question": "What are the temporary finger-like projections used by Amoeba for locomotion and engulfing food called?", "options": ["Flagella", "Cilia", "Pseudopodia", "Root hairs"], "correctIndex": 2, "explanation": "Pseudopodia ('false feet') are cytoplasmic extensions that help Amoeba crawl and surround food particles by phagocytosis.", "ncertRef": "CHS Core • Unicellular Organisms"}, {"id": 46, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Medium", "question": "What is the typical shape of smooth muscle cells, and how does it aid their function?", "options": ["Cube-shaped to store maximum starch", "Disc-shaped to float in water", "Spindle-shaped (tapering at both ends) to allow smooth contraction and relaxation", "Star-shaped to absorb sunlight"], "correctIndex": 2, "explanation": "Spindle-shaped muscle cells slide and contract efficiently to produce movement in organs like the stomach and intestine.", "ncertRef": "CHS Conceptual • Structure & Function"}, {"id": 47, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Hard", "question": "Why do mature human Red Blood Cells (RBCs) lack a nucleus and have a biconcave disc shape?", "options": ["To help them divide rapidly in the bloodstream", "Because RBCs are non-living dead cells from birth", "To maximize surface area and pack more haemoglobin for efficient oxygen transport", "To store chlorophyll for photosynthesis"], "correctIndex": 2, "explanation": "Lacking a nucleus and having a biconcave shape gives RBCs extra room for haemoglobin and flexibility to squeeze through tiny capillaries.", "ncertRef": "CHS High-Yield • Structure & Function"}, {"id": 48, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Medium", "question": "What shape are the guard cells that surround stomatal pores on a plant leaf?", "options": ["Bean-shaped or kidney-shaped", "Triangular", "Spiral-shaped", "Needle-shaped"], "correctIndex": 0, "explanation": "Pairs of bean-shaped (kidney-shaped) guard cells swell and shrink to open and close stomata for gas exchange and transpiration.", "ncertRef": "CHS Core • Plant Anatomy"}, {"id": 49, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Medium", "question": "Why are nerve cells long and highly branched at their ends?", "options": ["To receive and transmit electrical messages rapidly between the brain and body parts", "To absorb water from the soil", "To trap dust particles in the lungs", "To store excess fat under the skin"], "correctIndex": 0, "explanation": "Dendrites and long axons allow neurons to form communication networks that carry signals swiftly across the entire body.", "ncertRef": "CHS Conceptual • Structure & Function"}, {"id": 50, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Easy", "question": "Which of the following correctly arranges the levels of biological organisation in a multicellular organism from simplest to most complex?", "options": ["Organ → Tissue → Cell → Organism → Organ System", "Cell → Tissue → Organ → Organ System → Organism", "Tissue → Cell → Organ → Organism → Organ System", "Cell → Organ → Tissue → Organ System → Organism"], "correctIndex": 1, "explanation": "Similar cells form tissues; tissues combine into organs; organs work together in organ systems; and organ systems make up a complete organism.", "ncertRef": "CHS Core • Levels of Organisation"}, {"id": 51, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Easy", "question": "A group of similar cells that have a common origin and perform a specific function together is called a:", "options": ["Tissue", "Organelle", "Organism", "Species"], "correctIndex": 0, "explanation": "Examples of tissues include muscular tissue (for movement), nervous tissue (for signalling), and xylem tissue (for water transport in plants).", "ncertRef": "CHS Core • Tissues"}, {"id": 52, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Easy", "question": "Does the size of individual cells in an elephant differ significantly from the size of cells in a mouse?", "options": ["No; an elephant is larger because it has far more cells, not much larger cells", "Yes; mouse cells lack nuclei so they are tiny", "Yes; every elephant cell is 100 times larger than a mouse cell", "No; elephants and mice have the exact same number of cells"], "correctIndex": 0, "explanation": "Cell size is related to function rather than body size; larger organisms simply possess a much greater total number of cells.", "ncertRef": "CHS Conceptual • Cell Size vs Body Size"}, {"id": 53, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Easy", "question": "Which of the following sets contains ONLY unicellular organisms?", "options": ["Paramecium, Moss, Fern, Fish", "Amoeba, Paramecium, Euglena, Bacteria", "Yeast, Earthworm, Frog, Spirogyra", "Amoeba, Hydra, Mushroom, Rose"], "correctIndex": 1, "explanation": "Amoeba, Paramecium, Euglena, and bacteria each consist of a single cell that performs all life functions independently.", "ncertRef": "CHS Core • Unicellular vs Multicellular"}, {"id": 54, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Medium", "question": "Which hair-like microscopic structures cover the entire body of Paramecium and beat rhythmically for swimming?", "options": ["Cilia", "Pseudopodia", "Tendrils", "Hyphae"], "correctIndex": 0, "explanation": "Paramecium is a slipper-shaped protozoan whose thousands of tiny cilia beat in coordinated waves for movement and sweeping food into its oral groove.", "ncertRef": "CHS High-Yield • Protozoa"}, {"id": 55, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Medium", "question": "Which whip-like tail structure helps bacteria like Salmonella and algae like Chlamydomonas swim in liquid?", "options": ["Flagellum", "Cell plate", "Vacuole", "Chloroplast"], "correctIndex": 0, "explanation": "Flagella are long whip-like appendages that rotate or undulate to propel motile microbes through water or bodily fluids.", "ncertRef": "CHS Core • Microbial Locomotion"}, {"id": 56, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Medium", "question": "What is the single fertilized cell formed by the fusion of a male gamete and a female gamete, from which every multicellular organism begins life?", "options": ["Zygote", "Nucleoid", "Tissue", "Spore"], "correctIndex": 0, "explanation": "Every sexually reproducing multicellular organism starts as a single diploid cell called a zygote, which divides repeatedly to form the body.", "ncertRef": "CHS Core • Reproduction & Development"}, {"id": 57, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Medium", "question": "Why are root hair cells in plants elongated into thin tubular extensions?", "options": ["To increase the surface area for absorbing water and dissolved minerals from soil", "To help the plant walk toward water", "To store oxygen bubbles", "To capture sunlight underground"], "correctIndex": 0, "explanation": "The long, thin projection of a root hair cell dramatically increases contact with soil water and minerals, speeding up absorption.", "ncertRef": "CHS Conceptual • Plant Cell Adaptation"}, {"id": 58, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Medium", "question": "Which of the following is an example of an 'Organ' rather than a cell or an organ system?", "options": ["Red blood cell", "Stomach", "Neuron", "Digestive system"], "correctIndex": 1, "explanation": "The stomach is an organ composed of muscular, epithelial, and connective tissues working together as part of the digestive system.", "ncertRef": "CHS Core • Levels of Organisation"}, {"id": 59, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Hard", "question": "In a boiled hen's egg, the white part (albumen) and the yellow yolk together represent:", "options": ["A colony of unicellular bacteria", "A single large cell surrounded by protective layers", "Non-cellular mineral crystals", "Millions of fully developed chick organs"], "correctIndex": 1, "explanation": "An unfertilized hen's egg is a single giant cell (the yolk with its germinal disc), surrounded by albumen and a calcareous shell for nourishment and protection.", "ncertRef": "CHS Conceptual • Giant Cells"}, {"id": 60, "topic": "Cell Diversity, Shapes & Levels of Organisation", "difficulty": "Hard", "question": "Assertion (A): Unicellular organisms like Amoeba can survive independently without tissues or organs.\nReason (R): A single cell in Amoeba performs nutrition, respiration, excretion, growth, and reproduction.", "options": ["Both A and R are true, and R is the correct explanation of A", "A is false, but R is true", "A is true, but R is false", "Both A and R are true, but R is NOT the correct explanation of A"], "correctIndex": 0, "explanation": "In unicellular organisms, there is no division of labour among tissues; the single cell carries out all vital life processes on its own.", "ncertRef": "CHS Assertion-Reason • Cell Biology"}, {"id": 61, "topic": "World of Microorganisms & Viruses", "difficulty": "Easy", "question": "Into which four major groups are cellular microorganisms traditionally classified?", "options": ["Bacteria, Fungi, Protozoa, and Algae", "Bacteria, Mosses, Ferns, and Insects", "Algae, Lichens, Corals, and Sponges", "Viruses, Worms, Fungi, and Reptiles"], "correctIndex": 0, "explanation": "Cellular microorganisms are grouped into Bacteria, Fungi, Protozoa, and Algae; viruses are considered separately because they are acellular.", "ncertRef": "CHS Core • Classification"}, {"id": 62, "topic": "World of Microorganisms & Viruses", "difficulty": "Easy", "question": "Why are viruses considered to be on the borderline between living and non-living things?", "options": ["They have a cell wall made of metal", "They remain inert crystals outside a host, but multiply rapidly inside a living host cell", "They perform photosynthesis only at night", "They breathe oxygen only when frozen"], "correctIndex": 1, "explanation": "Outside a host cell, viruses show no signs of life (no metabolism or growth), but once inside a living cell, they hijack its machinery to replicate.", "ncertRef": "CHS Exam Favorite • Viruses"}, {"id": 63, "topic": "World of Microorganisms & Viruses", "difficulty": "Medium", "question": "What is a virus that specifically infects and destroys bacterial cells called?", "options": ["Antibiotic", "Bacteriophage", "Mycoplasma", "Protozoan"], "correctIndex": 1, "explanation": "Bacteriophages ('bacteria eaters') are viruses that attach to bacteria, inject their genetic material, and reproduce inside them.", "ncertRef": "CHS High-Yield • Viruses"}, {"id": 64, "topic": "World of Microorganisms & Viruses", "difficulty": "Medium", "question": "Rod-shaped bacteria (such as Lactobacillus and E. coli) are scientifically termed:", "options": ["Cocci", "Vibrios", "Bacilli", "Spirilla"], "correctIndex": 2, "explanation": "Bacteria are classified by shape into Cocci (spherical), Bacilli (rod-shaped), Spirilla (spiral), and Vibrio (comma-shaped).", "ncertRef": "CHS High-Yield • Bacterial Shapes"}, {"id": 65, "topic": "World of Microorganisms & Viruses", "difficulty": "Medium", "question": "Comma-shaped bacteria, such as the one that causes cholera (Vibrio cholerae), are called:", "options": ["Bacillus", "Coccus", "Vibrio", "Spirillum"], "correctIndex": 2, "explanation": "Vibrio refers to curved, comma-shaped bacteria; Vibrio cholerae causes cholera through contaminated water.", "ncertRef": "CHS High-Yield • Bacterial Shapes"}, {"id": 66, "topic": "World of Microorganisms & Viruses", "difficulty": "Easy", "question": "Which of the following fungi is unicellular and reproduces mainly by budding?", "options": ["Penicillium", "Mushroom (Agaricus)", "Yeast", "Bread mould (Rhizopus)"], "correctIndex": 2, "explanation": "Unlike most fungi that form multicellular thread-like hyphae, yeast (Saccharomyces cerevisiae) is a unicellular fungus that reproduces by budding.", "ncertRef": "CHS Exam Favorite • Fungi"}, {"id": 67, "topic": "World of Microorganisms & Viruses", "difficulty": "Medium", "question": "The cottony greenish-grey or black filamentous growth that appears on moist, stale bread is mainly caused by:", "options": ["Lactobacillus", "Bread mould (Rhizopus)", "Amoeba", "Chlamydomonas"], "correctIndex": 1, "explanation": "Rhizopus is a saprophytic fungus whose airborne spores germinate on moist, warm bread to form a network of hyphae and dark spore-bearing sporangia.", "ncertRef": "CHS Core • Fungi"}, {"id": 68, "topic": "World of Microorganisms & Viruses", "difficulty": "Medium", "question": "Which microscopic green organism is a unicellular alga that can swim using two flagella?", "options": ["Chlamydomonas", "Spirogyra", "Plasmodium", "Rhizopus"], "correctIndex": 0, "explanation": "Chlamydomonas is a unicellular, motile green alga with a cup-shaped chloroplast and two anterior flagella.", "ncertRef": "CHS High-Yield • Algae"}, {"id": 69, "topic": "World of Microorganisms & Viruses", "difficulty": "Medium", "question": "Which filamentous green alga found in freshwater ponds has distinctive ribbon-like, spiral-shaped chloroplasts?", "options": ["Paramecium", "Spirogyra", "Amoeba", "Yeast"], "correctIndex": 1, "explanation": "Spirogyra (pond silk) is a multicellular filamentous alga named after its helical, spiral-shaped chloroplasts.", "ncertRef": "CHS High-Yield • Algae"}, {"id": 70, "topic": "World of Microorganisms & Viruses", "difficulty": "Hard", "question": "Which unicellular organism is considered a connecting link between plants and animals because it has chlorophyll for photosynthesis yet feeds like an animal in the dark?", "options": ["Rhizobium", "Euglena", "Paramecium", "Yeast"], "correctIndex": 1, "explanation": "Euglena has chloroplasts to make food in sunlight (autotrophic) and can engulf organic matter in darkness (heterotrophic), lacking a rigid cell wall.", "ncertRef": "CHS Exam Favorite • Protists"}, {"id": 71, "topic": "World of Microorganisms & Viruses", "difficulty": "Easy", "question": "Which group of microorganisms contains chlorophyll and can prepare its own food by photosynthesis?", "options": ["Viruses", "Fungi", "Algae", "Most Protozoa"], "correctIndex": 2, "explanation": "Algae possess chlorophyll and perform photosynthesis, acting as primary producers in aquatic ecosystems.", "ncertRef": "CHS Core • Nutrition in Microbes"}, {"id": 72, "topic": "World of Microorganisms & Viruses", "difficulty": "Medium", "question": "Why can fungi such as bread mould and mushrooms NOT perform photosynthesis?", "options": ["They have too many chloroplasts", "They live only in boiling lava", "They lack the green pigment chlorophyll", "They do not have DNA"], "correctIndex": 2, "explanation": "Fungi lack chlorophyll and obtain nutrition heterotrophically—either as saprophytes feeding on dead organic matter or as parasites.", "ncertRef": "CHS Core • Fungi Nutrition"}, {"id": 73, "topic": "World of Microorganisms & Viruses", "difficulty": "Medium", "question": "Microorganisms that survive in extreme environments such as boiling hot springs, polar ice, and highly salty lakes are called:", "options": ["Amphibians", "Herbivores", "Epiphytes", "Extremophiles"], "correctIndex": 3, "explanation": "Extremophiles (many of which are Archaea and specialized bacteria) have unique enzymes and membranes that let them thrive where most life cannot.", "ncertRef": "CHS High-Yield • Habitats"}, {"id": 74, "topic": "World of Microorganisms & Viruses", "difficulty": "Easy", "question": "Find the ODD one out based on microbial group classification:", "options": ["Paramecium", "Plasmodium", "Amoeba", "Penicillium"], "correctIndex": 3, "explanation": "Amoeba, Paramecium, and Plasmodium are all protozoa, whereas Penicillium is a fungus.", "ncertRef": "CHS Odd-One-Out • Classification"}, {"id": 75, "topic": "World of Microorganisms & Viruses", "difficulty": "Medium", "question": "Find the ODD one out based on whether the organism is cellular or acellular:", "options": ["Yeast", "Influenza virus", "Lactobacillus", "Chlamydomonas"], "correctIndex": 1, "explanation": "Lactobacillus (bacterium), Chlamydomonas (alga), and Yeast (fungus) are cellular organisms, while Influenza virus is acellular.", "ncertRef": "CHS Odd-One-Out • Viruses"}, {"id": 76, "topic": "World of Microorganisms & Viruses", "difficulty": "Hard", "question": "Blue-green algae (such as Nostoc and Anabaena) are scientifically classified as:", "options": ["Multicellular fungi", "Animal-like protozoa", "Plant viruses", "Cyanobacteria (photosynthetic prokaryotes)"], "correctIndex": 3, "explanation": "Despite the common name 'blue-green algae', Nostoc and Anabaena are prokaryotic bacteria (cyanobacteria) capable of both photosynthesis and nitrogen fixation.", "ncertRef": "CHS Exam Favorite • Cyanobacteria"}, {"id": 77, "topic": "World of Microorganisms & Viruses", "difficulty": "Medium", "question": "What is the thread-like branching body filament of a multicellular fungus called?", "options": ["Hypha (plural: Hyphae)", "Chloroplast", "Pseudopodium", "Flagellum"], "correctIndex": 0, "explanation": "Multicellular fungi grow as microscopic tubular filaments called hyphae, which interweave to form a mass known as a mycelium.", "ncertRef": "CHS High-Yield • Fungal Structure"}, {"id": 78, "topic": "World of Microorganisms & Viruses", "difficulty": "Hard", "question": "Which microscopic algae form intricate glass-like shells made of silica and serve as major producers in oceans?", "options": ["Plasmodium", "Vibrio", "Rhizopus", "Diatoms"], "correctIndex": 3, "explanation": "Diatoms are unicellular microalgae encased in silica cell walls; their accumulated shells form diatomaceous earth.", "ncertRef": "CHS High-Yield • Microalgae"}, {"id": 79, "topic": "World of Microorganisms & Viruses", "difficulty": "Medium", "question": "How do most bacteria reproduce rapidly under favourable conditions of warmth and nutrients?", "options": ["Seed formation", "Regeneration by limbs", "Pollination", "Binary fission"], "correctIndex": 3, "explanation": "In binary fission, a single bacterial cell copies its DNA and splits into two identical daughter cells—sometimes every 20 minutes.", "ncertRef": "CHS Core • Microbial Reproduction"}, {"id": 80, "topic": "World of Microorganisms & Viruses", "difficulty": "Hard", "question": "Assertion (A): Microorganisms are found in almost every habitat on Earth, including inside the human gut.\nReason (R): Beneficial gut bacteria help digest food and synthesize essential vitamins like Vitamin K and Vitamin B12.", "options": ["Both A and R are true, and R is a valid supporting fact about human gut microbes", "A is false, but R is true", "Both A and R are false", "A is true, but R is false"], "correctIndex": 0, "explanation": "The human intestine hosts trillions of helpful microbes (gut microbiome) that aid digestion, produce Vitamin K and B-complex vitamins, and crowd out pathogens.", "ncertRef": "CHS Assertion-Reason • Microbiome"}, {"id": 81, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Easy", "question": "Which bacterium converts warm milk into curd?", "options": ["Plasmodium", "Vibrio cholerae", "Lactobacillus", "Rhizobium"], "correctIndex": 2, "explanation": "Lactobacillus multiplies in warm milk and converts milk sugar (lactose) into lactic acid, which coagulates milk proteins to form curd.", "ncertRef": "CHS Core • Friendly Microbes"}, {"id": 82, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Medium", "question": "Which acid is produced by Lactobacillus during curd formation, giving curd its tangy sour taste?", "options": ["Acetic acid", "Lactic acid", "Hydrochloric acid", "Citric acid"], "correctIndex": 1, "explanation": "Lactobacillus ferments lactose sugar into lactic acid, lowering the pH so milk casein proteins curdle and taste mildly sour.", "ncertRef": "CHS High-Yield • Biochemistry of Curd"}, {"id": 83, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Medium", "question": "Why does milk turn into curd faster in summer than in winter?", "options": ["Warm temperatures (around 35°C–40°C) accelerate the growth and reproduction of Lactobacillus", "Sunlight directly converts milk fat into curd", "Cold air destroys lactose sugar in winter", "Lactobacillus can only live in July"], "correctIndex": 0, "explanation": "Bacteria reproduce much faster at warm optimum temperatures; cold temperatures slow down bacterial enzyme activity.", "ncertRef": "CHS Conceptual • Applied Science"}, {"id": 84, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Easy", "question": "The process by which yeast converts sugar into alcohol and carbon dioxide in the absence of oxygen is called:", "options": ["Fermentation", "Photosynthesis", "Pasteurization", "Transpiration"], "correctIndex": 0, "explanation": "Fermentation is anaerobic breakdown of sugars by yeast or bacteria into alcohol (or acids) and carbon dioxide.", "ncertRef": "CHS Core • Fermentation"}, {"id": 85, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Easy", "question": "Who discovered the process of fermentation in 1857, proving it is caused by living microorganisms like yeast?", "options": ["Alexander Fleming", "Edward Jenner", "Louis Pasteur", "Robert Hooke"], "correctIndex": 2, "explanation": "French microbiologist Louis Pasteur discovered in 1857 that fermentation is carried out by living yeast cells, not purely chemical decay.", "ncertRef": "CHS Exam Favorite • Scientists"}, {"id": 86, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Easy", "question": "Which gas released by yeast during respiration makes bread dough, cakes, and idli batter rise and become soft and fluffy?", "options": ["Carbon dioxide (CO₂)", "Hydrogen (H₂)", "Nitrogen (N₂)", "Oxygen (O₂)"], "correctIndex": 0, "explanation": "Yeast respires and releases bubbles of carbon dioxide gas, which get trapped in the elastic dough and increase its volume.", "ncertRef": "CHS Core • Baking & Fermentation"}, {"id": 87, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Medium", "question": "Why does freshly fermented fruit juice or dough left overnight with yeast develop a characteristic alcoholic smell?", "options": ["Oxygen reacts with salt to form vinegar", "Yeast converts sugar into ethanol (ethyl alcohol) during anaerobic fermentation", "Bacteria convert water into petrol", "Yeast produces hydrochloric acid"], "correctIndex": 1, "explanation": "During anaerobic fermentation of sugars, yeast yields ethanol (alcohol) and carbon dioxide.", "ncertRef": "CHS Conceptual • Fermentation"}, {"id": 88, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Medium", "question": "Which bacterium is used commercially to convert ethanol (alcohol) into acetic acid (vinegar)?", "options": ["Mycobacterium", "Acetobacter", "Rhizobium", "Lactobacillus"], "correctIndex": 1, "explanation": "Acetobacter aceti oxidizes ethanol in the presence of oxygen to produce acetic acid, the main acid in vinegar.", "ncertRef": "CHS High-Yield • Industrial Microbiology"}, {"id": 89, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Easy", "question": "Which nitrogen-fixing bacterium lives symbiotically inside the root nodules of leguminous plants like peas, beans, and gram?", "options": ["Streptococcus", "Rhizobium", "Lactobacillus", "Salmonella"], "correctIndex": 1, "explanation": "Rhizobium converts atmospheric nitrogen gas (N₂) into soluble nitrates that legumes can absorb, while receiving food and shelter from the plant.", "ncertRef": "CHS Exam Favorite • Nitrogen Fixation"}, {"id": 90, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Medium", "question": "Why can green plants NOT directly absorb atmospheric nitrogen gas (N₂), even though it makes up about 78% of air?", "options": ["Plants do not need nitrogen to make proteins", "Nitrogen gas is too heavy to reach plant leaves", "Plant stomata permanently block nitrogen", "Nitrogen gas is chemically unreactive; plants can only absorb it as soluble compounds like nitrates and ammonium salts"], "correctIndex": 3, "explanation": "Atmospheric N₂ has a very strong triple bond; nitrogen-fixing bacteria or lightning must convert it into usable soluble nitrates first.", "ncertRef": "CHS Conceptual • Nitrogen Cycle"}, {"id": 91, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Medium", "question": "What type of ecological relationship exists between Rhizobium bacteria and leguminous plants?", "options": ["Competition", "Parasitism", "Predation", "Symbiosis (Mutualism)"], "correctIndex": 3, "explanation": "Both partners benefit: Rhizobium supplies fixed nitrogen compounds to the legume, and the legume supplies carbohydrates and a safe home in root nodules.", "ncertRef": "CHS Core • Symbiosis"}, {"id": 92, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Medium", "question": "Why do farmers often practice crop rotation by growing leguminous crops (like peas or pulses) between two cereal crops (like wheat or rice)?", "options": ["Because cereal crops produce nitrogen gas", "To kill all earthworms in the field", "To naturally replenish soil nitrogen fertility without excessive chemical fertilizers", "To reduce the water-holding capacity of soil"], "correctIndex": 2, "explanation": "Legume root nodules containing Rhizobium enrich the soil with usable nitrogen compounds needed by the next cereal crop.", "ncertRef": "CHS Application • Agriculture"}, {"id": 93, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Hard", "question": "Besides Rhizobium, which free-living soil bacterium and which blue-green algae fix atmospheric nitrogen directly in soil or paddy fields?", "options": ["Plasmodium and Amoeba", "Yeast and Bread mould", "Vibrio and Salmonella", "Azotobacter (bacterium) and Nostoc / Anabaena (blue-green algae)"], "correctIndex": 3, "explanation": "Free-living Azotobacter in soil and cyanobacteria (Nostoc, Anabaena) in waterlogged rice fields fix atmospheric nitrogen naturally.", "ncertRef": "CHS High-Yield • Biofertilizers"}, {"id": 94, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Medium", "question": "Besides nitrogen-fixing microbes, which natural atmospheric phenomenon also fixes nitrogen gas into nitrogen oxides that dissolve in rain?", "options": ["Ocean tides", "Earthquakes", "Lunar eclipses", "Lightning"], "correctIndex": 3, "explanation": "The extreme heat and electrical energy of lightning cause atmospheric nitrogen and oxygen to combine into nitrogen oxides, which rain down as dilute nitric acid.", "ncertRef": "CHS Core • Nitrogen Cycle"}, {"id": 95, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Hard", "question": "In the Nitrogen Cycle, the conversion of ammonia into nitrites and then into nitrates by soil bacteria (like Nitrosomonas and Nitrobacter) is called:", "options": ["Pasteurization", "Fermentation", "Nitrification", "Denitrification"], "correctIndex": 2, "explanation": "Nitrifying bacteria oxidize ammonia into nitrites (Nitrosomonas) and then into plant-usable nitrates (Nitrobacter).", "ncertRef": "CHS High-Yield • Nitrogen Cycle"}, {"id": 96, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Hard", "question": "Which process returns nitrogen gas (N₂) back into the atmosphere from soil nitrates, keeping atmospheric nitrogen constant at ~78%?", "options": ["Denitrification (by bacteria such as Pseudomonas)", "Photosynthesis", "Nitrogen fixation", "Ammonification"], "correctIndex": 0, "explanation": "Denitrifying bacteria convert soil nitrates back into free nitrogen gas (N₂), completing the Nitrogen Cycle.", "ncertRef": "CHS Exam Favorite • Nitrogen Cycle"}, {"id": 97, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Medium", "question": "Why is nitrogen an indispensable nutrient for all living organisms?", "options": ["It is the main component of pure water", "It replaces oxygen during breathing", "It is an essential component of proteins, nucleic acids (DNA/RNA), chlorophyll, and vitamins", "It provides calcium for bones"], "correctIndex": 2, "explanation": "Without nitrogen, organisms cannot synthesize amino acids (proteins) or genetic material (DNA and RNA).", "ncertRef": "CHS Conceptual • Nutrition"}, {"id": 98, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Medium", "question": "Which combination of microbes is involved in fermenting soaked rice and urad dal batter to make soft, spongy idli and dosa?", "options": ["Penicillium and Bacteriophages", "Rhizobium and Diatoms", "Naturally occurring lactic acid bacteria and wild yeasts", "Plasmodium and Dengue virus"], "correctIndex": 2, "explanation": "Lactic acid bacteria give mild tanginess while yeasts and bacteria release CO₂ bubbles that aerate and leaven the idli/dosa batter.", "ncertRef": "CHS Application • Traditional Food Science"}, {"id": 99, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Hard", "question": "What is the biological term for the conversion of nitrogenous compounds in dead plants, animals, and waste back into ammonia by decomposer bacteria and fungi?", "options": ["Denitrification", "Ammonification", "Pasteurization", "Vaccination"], "correctIndex": 1, "explanation": "Decomposers break down proteins and urea from dead organisms into ammonia (NH₃) in a step called ammonification.", "ncertRef": "CHS High-Yield • Nitrogen Cycle"}, {"id": 100, "topic": "Friendly Microbes: Food, Fermentation & Nitrogen Cycle", "difficulty": "Easy", "question": "Why is sugar often added alongside yeast when preparing warm dough for baking bread?", "options": ["Sugar removes all moisture from the dough", "Sugar turns the flour blue", "Sugar kills the yeast immediately", "Sugar serves as food for yeast so it can respire rapidly and release more CO₂"], "correctIndex": 3, "explanation": "Yeast uses simple sugars as its energy source during fermentation, speeding up carbon dioxide production to make dough rise quickly.", "ncertRef": "CHS Conceptual • Baking Science"}, {"id": 101, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Easy", "question": "Who accidentally discovered the world's first true antibiotic, Penicillin, in 1928?", "options": ["Louis Pasteur", "Robert Koch", "Alexander Fleming", "Edward Jenner"], "correctIndex": 2, "explanation": "In 1928, Scottish bacteriologist Alexander Fleming noticed that the mould Penicillium notatum prevented bacterial growth on a culture plate, leading to Penicillin.", "ncertRef": "CHS Exam Favorite • Antibiotics"}, {"id": 102, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Easy", "question": "From which type of microorganism was the antibiotic Penicillin originally obtained?", "options": ["A green alga", "A fungus (mould — Penicillium notatum)", "A protozoan", "A virus"], "correctIndex": 1, "explanation": "Penicillin is produced by the green mould Penicillium, a fungus that naturally secretes this chemical to inhibit competing bacteria.", "ncertRef": "CHS Core • Antibiotics"}, {"id": 103, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Medium", "question": "Why are antibiotics NOT effective against common cold, flu, or dengue fever?", "options": ["Because viruses are larger than bacteria", "Because cold and flu are caused by fungi", "Because these diseases are caused by viruses, and antibiotics target bacterial structures/processes", "Because antibiotics only work on plants"], "correctIndex": 2, "explanation": "Antibiotics disrupt bacterial cell walls or bacterial protein synthesis; viruses lack cell walls and use host machinery, so antibiotics cannot kill them.", "ncertRef": "CHS Exam Favorite • Medicine"}, {"id": 104, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Medium", "question": "Which of the following groups lists ONLY well-known antibiotics?", "options": ["Sodium benzoate, Vinegar, Salt, Sugar", "Penicillin, Streptomycin, Tetracycline, Erythromycin", "Insulin, Adrenaline, Thyroxine, Oestrogen", "Chlorophyll, Haemoglobin, Keratin, Cellulose"], "correctIndex": 1, "explanation": "Penicillin, Streptomycin, Tetracycline, and Erythromycin are widely used antibiotics derived from fungi and bacteria to treat bacterial infections.", "ncertRef": "CHS Core • Antibiotics"}, {"id": 105, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Easy", "question": "Who discovered the first vaccine in 1798, protecting humans against smallpox?", "options": ["Alexander Fleming", "Edward Jenner", "Antonie van Leeuwenhoek", "Robert Hooke"], "correctIndex": 1, "explanation": "English physician Edward Jenner developed the smallpox vaccine in 1798 using cowpox material, laying the foundation of immunology.", "ncertRef": "CHS Exam Favorite • Vaccines"}, {"id": 106, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Medium", "question": "How does a vaccine protect our body against a specific infectious disease?", "options": ["It introduces dead or weakened microbes so the immune system produces antibodies and remembers how to fight them", "It permanently coats the stomach with oil", "It kills all red blood cells in the body", "It replaces our DNA with bacterial DNA"], "correctIndex": 0, "explanation": "Vaccines train the immune system to recognize a pathogen and produce protective antibodies quickly if the real microbe ever enters the body.", "ncertRef": "CHS Core • Immunity"}, {"id": 107, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Easy", "question": "Malaria is caused by a protozoan called Plasmodium. Which insect acts as its carrier (vector)?", "options": ["Female Anopheles mosquito", "Housefly", "Male Anopheles mosquito", "Female Aedes mosquito"], "correctIndex": 0, "explanation": "Only the female Anopheles mosquito feeds on blood and transmits the malarial parasite Plasmodium from an infected person to a healthy person.", "ncertRef": "CHS Exam Favorite • Vector-Borne Diseases"}, {"id": 108, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Easy", "question": "Which mosquito acts as the carrier (vector) for the Dengue virus?", "options": ["Female Anopheles mosquito", "Honeybee", "Tsetse fly", "Female Aedes mosquito"], "correctIndex": 3, "explanation": "The Aedes aegypti mosquito (often with white stripes on its legs) breeds in clean stagnant water and transmits Dengue and Chikungunya viruses.", "ncertRef": "CHS Exam Favorite • Vector-Borne Diseases"}, {"id": 109, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Medium", "question": "Which of the following pairs of human diseases are BOTH caused by bacteria?", "options": ["Tuberculosis and Typhoid", "Chickenpox and Hepatitis A", "Malaria and Amoebic dysentery", "Polio and Measles"], "correctIndex": 0, "explanation": "Tuberculosis (Mycobacterium tuberculosis), Typhoid (Salmonella typhi), and Cholera (Vibrio cholerae) are bacterial diseases; Polio, Measles, Chickenpox, and Hepatitis A are viral.", "ncertRef": "CHS High-Yield • Human Diseases"}, {"id": 110, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Medium", "question": "Which of the following pairs of human diseases are BOTH caused by viruses?", "options": ["Cholera and Tuberculosis", "Typhoid and Anthrax", "Polio and Measles", "Malaria and Ringworm"], "correctIndex": 2, "explanation": "Polio, Measles, Chickenpox, Dengue, Influenza, and Hepatitis A are viral diseases.", "ncertRef": "CHS High-Yield • Human Diseases"}, {"id": 111, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Hard", "question": "Who discovered the bacterium Bacillus anthracis (the cause of anthrax disease in cattle and humans) in 1876?", "options": ["Edward Jenner", "Robert Brown", "Robert Koch", "Matthias Schleiden"], "correctIndex": 2, "explanation": "German physician Robert Koch isolated Bacillus anthracis in 1876 and also discovered the bacteria causing tuberculosis and cholera.", "ncertRef": "CHS High-Yield • Scientists"}, {"id": 112, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Medium", "question": "Match the plant disease with its correct causative microorganism: Citrus canker — Rust of wheat — Yellow vein mosaic of bhindi (okra).", "options": ["Virus — Bacteria — Fungi", "Protozoa — Algae — Bacteria", "Bacteria — Fungi — Virus", "Fungi — Virus — Bacteria"], "correctIndex": 2, "explanation": "Citrus canker is caused by bacteria (airborne), Rust of wheat is caused by fungi (air/seeds), and Yellow vein mosaic of bhindi is caused by a virus (spread by insects).", "ncertRef": "CHS Exam Favorite • Plant Diseases"}, {"id": 113, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Medium", "question": "Foot and Mouth disease in cattle is caused by which type of microorganism?", "options": ["Alga", "Virus", "Fungus", "Bacterium"], "correctIndex": 1, "explanation": "Foot and Mouth disease is a highly contagious viral disease affecting cloven-hoofed livestock such as cattle, buffalo, sheep, and goats.", "ncertRef": "CHS High-Yield • Animal Diseases"}, {"id": 114, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Easy", "question": "Why is milk heated to about 70°C for 15 to 30 seconds and then suddenly chilled and stored?", "options": ["To turn the milk directly into butter", "To add carbon dioxide gas to the milk", "To kill harmful microbes without boiling away nutrients — a process called Pasteurization", "To remove all calcium from the milk"], "correctIndex": 2, "explanation": "Discovered by Louis Pasteur, pasteurization destroys pathogenic microbes in milk and slows spoilage so it can be consumed safely without boiling.", "ncertRef": "CHS Exam Favorite • Pasteurization"}, {"id": 115, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Medium", "question": "Which two common chemical preservatives are widely added to jams, squashes, and packaged fruit juices to check microbial spoilage?", "options": ["Sodium benzoate and Sodium metabisulphite", "Sodium chloride and Baking soda", "Hydrochloric acid and Copper sulphate", "Urea and Ammonium nitrate"], "correctIndex": 0, "explanation": "Sodium benzoate and sodium metabisulphite are approved food-grade chemical preservatives that inhibit fungal and bacterial growth in jams and squashes.", "ncertRef": "CHS Exam Favorite • Food Preservation"}, {"id": 116, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Medium", "question": "How do high concentrations of common salt (in pickles, fish, meat) and sugar (in jams, jellies) preserve food from spoiling?", "options": ["They draw out moisture (water) from food and microbes, inhibiting microbial growth", "They supply oxygen to bacteria", "They freeze the food below 0°C", "They dissolve all proteins in the food"], "correctIndex": 0, "explanation": "Microbes need water to survive and multiply; high salt or sugar creates an osmotic environment that dehydrates microbial cells and halts spoilage.", "ncertRef": "CHS Conceptual • Food Preservation"}, {"id": 117, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Easy", "question": "Why does storing cooked food in a refrigerator keep it fresh for a longer time?", "options": ["Low temperature permanently destroys all bacteria instantly", "Refrigerators pump nitrogen gas into the food", "Low temperature slows down the growth and multiplication of spoilage microbes", "Cold air turns bacteria into vitamins"], "correctIndex": 2, "explanation": "Refrigeration (around 4°C) does not usually kill all microbes, but it dramatically slows their metabolic rate and reproduction.", "ncertRef": "CHS Core • Food Preservation"}, {"id": 118, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Medium", "question": "Why should we always complete the full course of antibiotics prescribed by a doctor, and never take them unnecessarily?", "options": ["Taking fewer doses makes vaccines stronger", "Antibiotics only work if taken on an empty stomach for one day", "Unfinished antibiotics turn into viruses inside the stomach", "Incomplete or unnecessary use can kill helpful gut bacteria and cause harmful bacteria to become antibiotic-resistant"], "correctIndex": 3, "explanation": "Stopping antibiotics early allows surviving bacteria to mutate and develop drug resistance, making future infections much harder to treat.", "ncertRef": "CHS Conceptual • Health Awareness"}, {"id": 119, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Easy", "question": "Why should water NOT be allowed to collect in coolers, flower pots, old tyres, and open containers around homes?", "options": ["Because Rhizobium bacteria multiply in tyres", "Because stagnant water produces carbon monoxide", "Because stagnant water attracts honeybees", "Because mosquitoes breed in stagnant water and spread diseases like malaria and dengue"], "correctIndex": 3, "explanation": "Eliminating stagnant water breaks the mosquito life cycle (eggs and larvae), effectively preventing malaria, dengue, and chikungunya.", "ncertRef": "CHS Core • Disease Prevention"}, {"id": 120, "topic": "Medicine, Immunity, Diseases & Food Preservation", "difficulty": "Hard", "question": "Which bacterial toxin produced in improperly canned or spoiled anaerobic food causes a dangerous form of food poisoning called botulism?", "options": ["Lactobacillus lactic acid", "Rhizobium nitrate", "Penicillium antibiotic", "Clostridium botulinum toxin"], "correctIndex": 3, "explanation": "Food poisoning occurs when microbes like Clostridium botulinum or Salmonella grow on food and release toxic substances that cause severe illness.", "ncertRef": "CHS High-Yield • Food Poisoning"}, {"id": 121, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Easy", "question": "Why are saprophytic bacteria and fungi called 'Nature's Scavengers' or 'Decomposers'?", "options": ["They block sunlight from reaching soil", "They break down dead plants, animals, and organic waste into simple nutrients that return to the soil", "They manufacture plastic bottles from leaves", "They hunt and eat live deer and rabbits"], "correctIndex": 1, "explanation": "Decomposers clean the environment by converting complex dead organic matter into rich humus and mineral nutrients that plants reuse.", "ncertRef": "CHS Core • Ecology"}, {"id": 122, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Easy", "question": "Which of the following materials can be broken down naturally into manure by soil microorganisms?", "options": ["Polythene bags and broken glass", "Aluminium foil and plastic bottles", "Vegetable peels, fallen leaves, and animal dung", "Iron nails and ceramic tiles"], "correctIndex": 2, "explanation": "Microorganisms can decompose biodegradable organic matter (plant and animal wastes), but cannot easily break down synthetic plastics, glass, or metals.", "ncertRef": "CHS Core • Biodegradable Waste"}, {"id": 123, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Medium", "question": "What is the main combustible gas present in biogas (gobar gas) produced by anaerobic decomposition of cattle dung?", "options": ["Nitrogen (N₂)", "Chlorine (Cl₂)", "Methane (CH₄)", "Oxygen (O₂)"], "correctIndex": 2, "explanation": "Biogas consists mainly of methane (about 55%–70%) along with carbon dioxide and traces of hydrogen sulphide, making it a clean renewable fuel.", "ncertRef": "CHS Exam Favorite • Biogas"}, {"id": 124, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Hard", "question": "Under what condition do methanogenic bacteria produce biogas from organic waste inside a biogas digester?", "options": ["Direct exposure to ultraviolet radiation", "Freezing temperature below -10°C", "High-oxygen aerobic condition", "Anaerobic condition (absence of oxygen)"], "correctIndex": 3, "explanation": "Methanogens are strict anaerobes; they digest animal dung and plant slurry in sealed oxygen-free tanks to release methane-rich biogas.", "ncertRef": "CHS High-Yield • Biogas"}, {"id": 125, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Medium", "question": "What is the eco-friendly process of using specialized microorganisms to clean up environmental pollutants like ocean oil spills called?", "options": ["Pasteurization", "Transpiration", "Fermentation", "Bioremediation"], "correctIndex": 3, "explanation": "Bioremediation employs pollutant-degrading microbes (such as oil-eating bacteria like Pseudomonas putida and Alcanivorax) to break down toxic spills into harmless water and CO₂.", "ncertRef": "CHS High-Yield • Environmental Science"}, {"id": 126, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Hard", "question": "Which Indian-American scientist famously developed a genetically engineered 'superbug' strain of Pseudomonas putida capable of breaking down crude oil spills?", "options": ["Dr. C. V. Raman", "Dr. Homi J. Bhabha", "Dr. Ananda Mohan Chakrabarty", "Dr. Vikram Sarabhai"], "correctIndex": 2, "explanation": "Dr. Ananda Mohan Chakrabarty engineered oil-eating Pseudomonas bacteria in the 1970s to help clean marine petroleum spills.", "ncertRef": "CHS High-Yield • Indian Scientists"}, {"id": 127, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Easy", "question": "Which nutrient-rich blue-green microalga is widely called a 'Superfood' because it contains over 60% protein along with vitamins and minerals?", "options": ["Plasmodium", "Vibrio", "Rhizopus", "Spirulina"], "correctIndex": 3, "explanation": "Spirulina is an edible, spiral-shaped cyanobacterium (microalga) packed with protein, iron, and Vitamin B12, used as a nutritional supplement and even studied for space missions.", "ncertRef": "CHS Exam Favorite • Microalgae"}, {"id": 128, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Medium", "question": "Which microscopic aquatic organisms produce more than half of the Earth's oxygen supply through photosynthesis?", "options": ["Microalgae and Phytoplankton", "Mushrooms and Bread mould", "Viruses and Protozoa", "Termites and Earthworms"], "correctIndex": 0, "explanation": "Marine microalgae and cyanobacteria (phytoplankton) absorb huge amounts of CO₂ and generate over 50% of the oxygen we breathe.", "ncertRef": "CHS High-Yield • Global Ecology"}, {"id": 129, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Medium", "question": "Which fast-growing unicellular green microalga is researched as both a high-protein food supplement for astronauts and a source of renewable biofuel?", "options": ["Mycobacterium", "Amoeba", "Lactobacillus", "Chlorella"], "correctIndex": 3, "explanation": "Chlorella is rich in protein and lipids, grows rapidly using sunlight and CO₂, and is explored for space life-support systems and biodiesel production.", "ncertRef": "CHS High-Yield • Microalgae"}, {"id": 130, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Medium", "question": "What happens to aquatic life when excess chemical fertilizers wash into a pond and trigger a massive overgrowth of algae (Algal Bloom)?", "options": ["Fish grow ten times faster due to extra plastic", "All bacteria in the pond freeze", "Decomposers consume dissolved oxygen while breaking down dead algae, causing fish to suffocate", "The pond water turns into pure distilled water"], "correctIndex": 2, "explanation": "Excessive nutrient enrichment (eutrophication) causes algal blooms; when the algae die, aerobic bacteria decompose them and deplete dissolved oxygen, killing fish.", "ncertRef": "CHS Conceptual • Eutrophication"}, {"id": 131, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Medium", "question": "How do aerobic bacteria help in modern municipal sewage treatment plants?", "options": ["They digest harmful organic matter in wastewater, reducing pollution before water is released", "They add heavy metals to drinking water", "They evaporate all water into the clouds", "They turn wastewater directly into crude oil"], "correctIndex": 0, "explanation": "In aeration tanks, helpful aerobic microbes break down human and household organic waste into harmless sludge and cleaner water.", "ncertRef": "CHS Application • Wastewater Treatment"}, {"id": 132, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Easy", "question": "What valuable agricultural by-product remains after biogas is extracted from cattle dung slurry in a biogas plant?", "options": ["Toxic plastic waste", "Radioactive ash", "Pure hydrochloric acid", "Nutrient-rich organic manure (slurry)"], "correctIndex": 3, "explanation": "The spent slurry from a biogas plant is rich in nitrogen and phosphorus and makes an excellent, odour-free organic fertilizer for crops.", "ncertRef": "CHS Core • Biogas"}, {"id": 133, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Medium", "question": "Why is making compost from kitchen vegetable peels and garden leaves better than burning dry leaves?", "options": ["Composting destroys all soil fertility", "Composting recycles nutrients into fertile manure using microbes without causing air pollution", "Composting takes less than 5 seconds", "Burning leaves produces oxygen gas"], "correctIndex": 1, "explanation": "Microbial composting converts organic waste into rich humus while avoiding the smoke and carbon monoxide released by open burning.", "ncertRef": "CHS Conceptual • Sustainability"}, {"id": 134, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Hard", "question": "How do certain symbiotic bacteria living in the digestive tract of herbivores like cows and buffaloes help them survive on grass?", "options": ["They convert grass directly into iron", "They perform photosynthesis inside the cow's stomach", "They secrete cellulase enzymes that digest tough plant cellulose, which mammals cannot digest on their own", "They prevent the cow from drinking water"], "correctIndex": 2, "explanation": "Ruminants rely on mutualistic rumen bacteria and protozoa to break down cellulose in plant cell walls into absorbable nutrients.", "ncertRef": "CHS High-Yield • Symbiosis"}, {"id": 135, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Medium", "question": "Which industrial product is obtained from red marine algae and is widely used as a solidifying gel in microbiology labs, ice creams, and jellies?", "options": ["Methane", "Ethanol", "Penicillin", "Agar-agar"], "correctIndex": 3, "explanation": "Agar (extracted from red algae like Gelidium and Gracilaria) forms a firm nutrient gel on Petri dishes for growing bacterial and fungal colonies.", "ncertRef": "CHS High-Yield • Algae Uses"}, {"id": 136, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Hard", "question": "Which dual organism is formed by a close symbiotic partnership between a fungus and an alga (or cyanobacterium) and acts as a natural indicator of air pollution?", "options": ["Lichen", "Plasmodium", "Bacteriophage", "Mushroom"], "correctIndex": 0, "explanation": "In lichens, the alga makes food via photosynthesis while the fungus provides water, minerals, and shelter; lichens do not grow in sulphur-dioxide polluted air.", "ncertRef": "CHS Exam Favorite • Symbiosis & Indicators"}, {"id": 137, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Medium", "question": "If all decomposer bacteria and fungi suddenly disappeared from Earth, what would be the most immediate consequence?", "options": ["All oceans would dry up within a week", "Dead bodies and organic wastes would pile up and essential soil nutrients would stop recycling", "Atmosphere would immediately run out of nitrogen gas", "Plants would grow twice as tall without minerals"], "correctIndex": 1, "explanation": "Without decomposers, mineral cycles would halt, locking carbon, nitrogen, and minerals inside dead organic matter.", "ncertRef": "CHS Conceptual • Ecosystem Balance"}, {"id": 138, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Hard", "question": "Which of the following matches is INCORRECT?", "options": ["Antonie van Leeuwenhoek — First observation of living bacteria", "Edward Jenner — Smallpox Vaccine", "Robert Hooke — Discovery of Cell", "Louis Pasteur — Discovery of Penicillin"], "correctIndex": 3, "explanation": "Alexander Fleming discovered Penicillin in 1928; Louis Pasteur is famous for discovering fermentation, pasteurization, and the rabies vaccine.", "ncertRef": "CHS Match Check • Scientists"}, {"id": 139, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Hard", "question": "Which of the following pairs is INCORRECTLY matched?", "options": ["Yeast — Baking of bread", "Penicillium — Production of antibiotic", "Rhizobium — Causes Malaria", "Lactobacillus — Setting of curd"], "correctIndex": 2, "explanation": "Rhizobium is a helpful nitrogen-fixing bacterium in legume roots; Malaria is caused by the protozoan Plasmodium.", "ncertRef": "CHS Match Check • Microbes"}, {"id": 140, "topic": "Microbes in Environment, Biogas & Microalgae", "difficulty": "Hard", "question": "Assertion (A): Microalgae like Spirulina and Chlorella are considered promising future sources of sustainable food and biofuel.\nReason (R): They grow rapidly using sunlight and CO₂, require little arable land, and are rich in proteins and oils.", "options": ["Both A and R are true, and R is the correct explanation of A", "Both A and R are true, but R is NOT the correct explanation of A", "A is true, but R is false", "A is false, but R is true"], "correctIndex": 0, "explanation": "Microalgae convert sunlight and CO₂ efficiently into nutrient-dense biomass and lipids without competing with traditional farmland.", "ncertRef": "CHS Assertion-Reason • Future Science"}]};
